<div class="page-title"><div><em>MULTI-CURRENCY</em><h1>Currency exchange</h1><p>Convert money between your accounts in different currencies.</p></div></div><div class="grid transfer-grid"><section class="panel form-panel"><div class="panel-head"><div><h2>Convert money</h2><p>Real-time rates between your accounts</p></div></div><?=form_open('exchange')?><label>From account</label><select name="from_account_id" id="fx-from" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" data-cur="<?=$a['currency']?>" data-bal="<?=html_escape($a['available_balance'])?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?> (<?=$a['currency']?>) — <?=money($a['available_balance'],$a['currency'])?></option><?php endforeach?></select><label>To account</label><select name="to_account_id" id="fx-to" required><?php foreach($accounts as $a):?><option value="<?=$a['id']?>" data-cur="<?=$a['currency']?>"><?=html_escape($a['name'])?> •<?=substr($a['account_number'],-4)?> (<?=$a['currency']?>)</option><?php endforeach?></select><label>Amount to exchange</label><input name="amount" id="fx-amount" type="number" step="0.01" min="0.01" required placeholder="0.00"><div class="fx-preview" id="fx-preview"></div><button class="btn wide">Exchange currency ›</button></form></section><aside class="panel transfer-info"><i>◎</i><h3>Exchange rates</h3><p>Current mid-market reference rates:</p><ul class="fx-rates"><?php foreach($rates as $r):?><li><b><?=$r['from_currency']?> → <?=$r['to_currency']?></b><span><?=number_format($r['rate'],4)?></span></li><?php endforeach?></ul><hr><small>Rates are provided for reference and are subject to change.</small></aside></div>
<script>(function(){var from=document.getElementById('fx-from'),to=document.getElementById('fx-to'),amt=document.getElementById('fx-amount'),pv=document.getElementById('fx-preview');function calc(){if(!from.value||!to.value||!amt.value)return;var fc=from.selectedOptions[0].dataset.cur,tc=to.selectedOptions[0].dataset.cur,a=parseFloat(amt.value);var rows=document.querySelectorAll('.fx-rates li');var rate=null;rows.forEach(function(r){var t=r.querySelector('b').textContent;if(t.trim()===(fc+' → '+tc))rate=parseFloat(r.querySelector('span').textContent);});pv.innerHTML='';if(fc===tc){pv.textContent='Choose two accounts with different currencies.';pv.className='fx-preview warn';return;}if(rate&&a){pv.className='fx-preview';pv.innerHTML='≈ <b>'+a.toFixed(2)+' '+fc+'</b> = <b>'+ (a*rate).toFixed(2)+' '+tc+'</b> <small>@ '+rate.toFixed(4)+'</small>';}}[from,to,amt].forEach(function(el){el.addEventListener('change',calc);el.addEventListener('input',calc);});})();</script>
